@Controller
public class QuizController {
    private final QuizRepository quizzes; private final QuizJogadorRepository jogadores; private final QuizRespostaRepository respostas; private final QuizBancoPerguntaRepository banco;
    private final EventoRepository eventos; private final UsuarioRepository usuarios; private final InscricaoRepository inscricoes; private final ObjectMapper mapper; private final sistema.eventos.service.FileStorageService files;
    public QuizController(QuizRepository quizzes, QuizJogadorRepository jogadores, QuizRespostaRepository respostas, QuizBancoPerguntaRepository banco, EventoRepository eventos, UsuarioRepository usuarios, InscricaoRepository inscricoes, ObjectMapper mapper, sistema.eventos.service.FileStorageService files) {
        this.quizzes=quizzes; this.jogadores=jogadores; this.respostas=respostas; this.banco=banco; this.eventos=eventos; this.usuarios=usuarios; this.inscricoes=inscricoes; this.mapper=mapper; this.files=files;
    }

    @GetMapping("/organizador/quizzes") public String lista(Authentication auth, Model model) {
        Usuario u=usuario(auth); model.addAttribute("quizzes",quizzes.findByOrganizadorIdOrderByIdDesc(u.getId()));
        model.addAttribute("eventos",eventos.findByOrganizadorId(u.getId())); return "quiz-lista";
    }
    @GetMapping("/organizador/quizzes/novo") public String novo(@RequestParam Long eventoId, Authentication auth, Model model) {
        Evento e=eventos.findById(eventoId).orElseThrow(); if(!e.getOrganizador().getId().equals(usuario(auth).getId())) throw new RuntimeException("Evento não encontrado.");
        model.addAttribute("evento",e); return "quiz-editor";
    }
    @PostMapping("/organizador/quizzes/salvar") @Transactional public String salvar(@RequestParam Long eventoId, @RequestParam String dados, Authentication auth) throws IOException {
        Usuario u=usuario(auth); Evento e=eventos.findById(eventoId).orElseThrow(); if(!e.getOrganizador().getId().equals(u.getId())) throw new RuntimeException("Acesso negado.");
        QuizInput input=mapper.readValue(dados,QuizInput.class); if(input.titulo==null||input.titulo.isBlank()||input.perguntas==null||input.perguntas.isEmpty()) throw new IllegalArgumentException("Informe um título e ao menos uma pergunta.");
        Quiz q=new Quiz(); q.setEvento(e); q.setOrganizador(u); q.setTitulo(input.titulo.trim()); q.setDescricao(input.descricao); q.setCodigo(codigo());
        q.setPontosFacil(valor(input.pontosFacil,500)); q.setPontosMedio(valor(input.pontosMedio,1000)); q.setPontosDificil(valor(input.pontosDificil,1500));
        List<QuizBancoPergunta> pool=new ArrayList<>();
        for(QuestionInput qi:input.perguntas){
            QuizBancoPergunta origem;
            if(qi.bancoId!=null){if(pool.stream().anyMatch(x->x.getId().equals(qi.bancoId)))throw new IllegalArgumentException("A mesma pergunta do banco não pode ser adicionada duas vezes.");origem=banco.findWithOwnerById(qi.bancoId).orElseThrow(()->new IllegalArgumentException("Pergunta do banco não encontrada."));if(!origem.getOrganizador().getId().equals(u.getId()))throw new IllegalArgumentException("A pergunta não pertence ao seu banco.");}
            else {if(qi.enunciado==null||qi.enunciado.isBlank()||qi.alternativas==null||qi.alternativas.size()<2||qi.alternativas.stream().filter(a->a.correta).count()!=1)throw new IllegalArgumentException("Cada pergunta precisa de pelo menos duas alternativas e uma correta.");origem=new QuizBancoPergunta();origem.setOrganizador(u);origem.setEnunciado(qi.enunciado.trim());origem.setImagemUrl(blank(qi.imagemUrl));origem.setDificuldade(QuizDificuldade.valueOf(qi.dificuldade==null?"MEDIO":qi.dificuldade));origem.setSegundos(Math.max(5,Math.min(120,qi.segundos==null?20:qi.segundos)));origem.setBonus(Boolean.TRUE.equals(qi.bonus));int oi=0;for(OptionInput ai:qi.alternativas){if(ai.texto==null||ai.texto.isBlank())continue;QuizBancoAlternativa ba=new QuizBancoAlternativa();ba.setPergunta(origem);ba.setTexto(ai.texto.trim());ba.setImagemUrl(blank(ai.imagemUrl));ba.setCorreta(ai.correta);ba.setOrdem(oi++);origem.getAlternativas().add(ba);}if(origem.getAlternativas().size()<2)throw new IllegalArgumentException("Cada pergunta precisa de pelo menos duas alternativas.");banco.save(origem);}
            pool.add(origem);
        }
        List<QuizBancoPergunta> selecionadas=new ArrayList<>(pool);
        boolean sorteio=input.quantidadeFacil!=null||input.quantidadeMedio!=null||input.quantidadeDificil!=null;
        if(sorteio){selecionadas.clear(); for(QuizDificuldade d:QuizDificuldade.values()){int qtd=d==QuizDificuldade.FACIL?Optional.ofNullable(input.quantidadeFacil).orElse(0):d==QuizDificuldade.MEDIO?Optional.ofNullable(input.quantidadeMedio).orElse(0):Optional.ofNullable(input.quantidadeDificil).orElse(0);List<QuizBancoPergunta> candidatos=pool.stream().filter(x->x.getDificuldade()==d).collect(Collectors.toCollection(ArrayList::new));Collections.shuffle(candidatos);if(qtd>candidatos.size())throw new IllegalArgumentException("O banco tem apenas "+candidatos.size()+" perguntas de nível "+d+".");selecionadas.addAll(candidatos.subList(0,qtd));}if(selecionadas.isEmpty())throw new IllegalArgumentException("Escolha quantas perguntas sortear por dificuldade.");Collections.shuffle(selecionadas);}
        int n=0; for(QuizBancoPergunta origem:selecionadas){
            QuizPergunta p=new QuizPergunta(); p.setQuiz(q); p.setEnunciado(origem.getEnunciado()); p.setImagemUrl(origem.getImagemUrl()); p.setDificuldade(origem.getDificuldade()); p.setSegundos(origem.getSegundos()); p.setBonus(origem.getBonus()); p.setOrdem(n++);
            int j=0; for(QuizBancoAlternativa ba:origem.getAlternativas()){QuizAlternativa a=new QuizAlternativa();a.setPergunta(p);a.setTexto(ba.getTexto());a.setImagemUrl(ba.getImagemUrl());a.setCorreta(ba.isCorreta());a.setOrdem(j++);p.getAlternativas().add(a);} q.getPerguntas().add(p);
        }
        quizzes.save(q); return "redirect:/organizador/quizzes/"+q.getId();
    }
    @GetMapping("/organizador/quizzes/{id}") @Transactional(readOnly=true) public String gerir(@PathVariable Long id,Authentication auth,Model model){Quiz q=owned(id,auth); model.addAttribute("quiz",q);model.addAttribute("rank",rank(q));model.addAttribute("qrData",qr(q.getCodigo()));model.addAttribute("roundStats",roundStats(q));return "quiz-gerir";}
    @PostMapping(value="/organizador/quizzes/imagem",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseBody public Map<String,String> imagem(@RequestPart("imagem") org.springframework.web.multipart.MultipartFile imagem){return Map.of("url",files.publicImageUrl(files.storeImage(imagem,"quiz")));}
    @GetMapping(value="/organizador/quizzes/banco",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody public List<Map<String,Object>> perguntasBanco(Authentication auth){return banco.findByOrganizadorIdOrderByIdDesc(usuario(auth).getId()).stream().map(p->Map.of("id",p.getId(),"enunciado",p.getEnunciado(),"imagemUrl",p.getImagemUrl()==null?"":p.getImagemUrl(),"dificuldade",p.getDificuldade().name(),"segundos",p.getSegundos(),"bonus",p.getBonus(),"alternativas",p.getAlternativas().stream().map(a->Map.of("texto",a.getTexto(),"imagemUrl",a.getImagemUrl()==null?"":a.getImagemUrl(),"correta",a.isCorreta())).toList())).toList();}
    @PostMapping("/organizador/quizzes/{id}/iniciar") @Transactional public String iniciar(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);if(q.getStatus()!=QuizStatus.RASCUNHO||q.getPerguntas().isEmpty())throw new IllegalArgumentException("O quiz precisa estar em rascunho e ter perguntas.");q.setStatus(QuizStatus.AGUARDANDO);q.setIniciadoEm(LocalDateTime.now());return "redirect:/organizador/quizzes/"+id;}
    @PostMapping("/organizador/quizzes/{id}/liberar") @Transactional public String liberar(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);if(q.getStatus()!=QuizStatus.AGUARDANDO&&q.getStatus()!=QuizStatus.EM_ANDAMENTO)throw new IllegalArgumentException("Inicie o quiz antes de liberar perguntas.");if(q.getPerguntaAtual()+1>=q.getPerguntas().size())throw new IllegalArgumentException("Todas as perguntas já foram liberadas.");if(q.getPerguntaAtual()>=0){Long anterior=q.getPerguntas().get(q.getPerguntaAtual()).getId();for(QuizJogador jogador:q.getJogadores())if(!respostas.existsByJogadorIdAndPerguntaId(jogador.getId(),anterior))jogador.setSequencia(0);}q.setPerguntaAtual(q.getPerguntaAtual()+1);q.setPerguntaLiberadaEm(LocalDateTime.now());q.setStatus(QuizStatus.EM_ANDAMENTO);return "redirect:/organizador/quizzes/"+id;}
    @PostMapping("/organizador/quizzes/{id}/encerrar") @Transactional public String encerrar(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);q.setStatus(QuizStatus.ENCERRADO);q.setEncerradoEm(LocalDateTime.now());return "redirect:/organizador/quizzes/"+id;}
    @GetMapping("/quiz/entrar/{codigo}") public String entrar(@PathVariable String codigo,Authentication auth,Model model){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();model.addAttribute("quiz",q);return "quiz-entrar";}
    @PostMapping("/quiz/entrar/{codigo}") @Transactional public String entrarPost(@PathVariable String codigo,@RequestParam(defaultValue="astronauta") String avatar,Authentication auth){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();Usuario u=usuario(auth);
        if(u.getPerfil()!=Perfil.ROLE_PARTICIPANTE)throw new IllegalArgumentException("Esta sala é exclusiva para participantes.");
        if(!inscricoes.existsByParticipanteIdAndEventoIdAndStatusNot(u.getId(),q.getEvento().getId(),StatusInscricao.CANCELADO)) throw new IllegalArgumentException("É necessário ter inscrição válida neste evento para participar.");
        if(q.getStatus()==QuizStatus.ENCERRADO)throw new IllegalArgumentException("Este quiz já foi encerrado.");
        if(jogadores.findByQuizIdAndUsuarioId(q.getId(),u.getId()).isEmpty()){QuizJogador j=new QuizJogador();j.setQuiz(q);j.setUsuario(u);j.setAvatar(avatar(avatar));j.setEntrouEm(LocalDateTime.now());jogadores.save(j);}
        return "redirect:/quiz/jogar/"+q.getCodigo();
    }
    @GetMapping("/quiz/jogar/{codigo}") public String jogar(@PathVariable String codigo,Authentication auth,Model model){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador j=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow(()->new IllegalArgumentException("Entre no quiz antes de jogar."));model.addAttribute("quiz",q);model.addAttribute("jogador",j);return "quiz-jogar";}
    @GetMapping(value="/quiz/{codigo}/estado",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody public Map<String,Object> estado(@PathVariable String codigo,Authentication auth){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador me=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow();Map<String,Object> out=new LinkedHashMap<>();out.put("status",q.getStatus());out.put("titulo",q.getTitulo());out.put("indice",q.getPerguntaAtual());out.put("total",q.getPerguntas().size());out.put("pontuacao",me.getPontuacao());
        out.put("rank",rank(q).stream().map(x->Map.of("nome",x.getUsuario().getNome(),"avatar",x.getAvatar(),"pontuacao",x.getPontuacao())).toList());
        if(q.getPerguntaAtual()>=0&&q.getPerguntaAtual()<q.getPerguntas().size()){QuizPergunta p=q.getPerguntas().get(q.getPerguntaAtual());long remaining=Math.max(0,p.getSegundos()*1000L-Duration.between(q.getPerguntaLiberadaEm(),LocalDateTime.now()).toMillis());out.put("tempoRestanteMs",remaining);out.put("pergunta",Map.of("id",p.getId(),"enunciado",p.getEnunciado(),"imagemUrl",p.getImagemUrl()==null?"":p.getImagemUrl(),"segundos",p.getSegundos(),"alternativas",p.getAlternativas().stream().map(a->Map.of("id",a.getId(),"texto",a.getTexto(),"imagemUrl",a.getImagemUrl()==null?"":a.getImagemUrl())).toList()));out.put("respondida",respostas.existsByJogadorIdAndPerguntaId(me.getId(),p.getId()));}
        else out.put("pergunta",null); return out;}
    @PostMapping(value="/quiz/{codigo}/responder",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody @Transactional public Map<String,Object> responder(@PathVariable String codigo,@RequestParam Long alternativaId,Authentication auth){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador j=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow();if(q.getStatus()!=QuizStatus.EM_ANDAMENTO||q.getPerguntaAtual()<0)throw new IllegalArgumentException("Ainda não há pergunta aberta.");QuizPergunta p=q.getPerguntas().get(q.getPerguntaAtual());if(respostas.existsByJogadorIdAndPerguntaId(j.getId(),p.getId()))throw new IllegalArgumentException("Resposta já enviada.");long elapsed=Math.max(0,Duration.between(q.getPerguntaLiberadaEm(),LocalDateTime.now()).toMillis());if(elapsed>p.getSegundos()*1000L)throw new IllegalArgumentException("O tempo para responder terminou.");QuizAlternativa a=p.getAlternativas().stream().filter(x->x.getId().equals(alternativaId)).findFirst().orElseThrow();int points=0;if(a.isCorreta()){j.setSequencia(j.getSequencia()+1);int base=switch(p.getDificuldade()){case FACIL->q.getPontosFacil();case MEDIO->q.getPontosMedio();case DIFICIL->q.getPontosDificil();};double multiplier=j.getSequencia()>=4?2.0:j.getSequencia()==3?1.5:j.getSequencia()==2?1.2:1.0;points=(int)Math.round(base*Math.max(.2,1.0-(double)elapsed/(p.getSegundos()*1000L))*(p.getBonus()?2:1)*multiplier);j.setPontuacao(j.getPontuacao()+points);}else j.setSequencia(0);QuizResposta r=new QuizResposta();r.setJogador(j);r.setPergunta(p);r.setAlternativa(a);r.setCorreta(a.isCorreta());r.setPontos(points);r.setTempoMs(elapsed);respostas.save(r);return Map.of("correta",a.isCorreta(),"pontos",points,"sequencia",j.getSequencia());}
    @GetMapping("/organizador/quizzes/{id}/relatorio") @Transactional(readOnly=true) public String relatorio(@PathVariable Long id,Authentication auth,Model model){Quiz q=owned(id,auth);List<Map<String,Object>> questionStats=questionReports(q);model.addAttribute("quiz",q);model.addAttribute("rank",rank(q));model.addAttribute("stats",reportStats(q));model.addAttribute("questionReports",questionStats);model.addAttribute("hasCriticalQuestion",questionStats.stream().anyMatch(x->(Integer)x.get("percentual")<35));model.addAttribute("playerReports",playerReports(q));return "quiz-relatorio";}
    @GetMapping("/organizador/quizzes/{id}/relatorio.xlsx") @Transactional(readOnly=true) public void xlsx(@PathVariable Long id,Authentication auth,HttpServletResponse res)throws IOException {Quiz q=owned(id,auth);List<QuizJogador> ordem=rank(q);List<QuizResposta> todas=respostas.findByJogadorQuizId(id);Map<String,QuizResposta> porPar=new HashMap<>();todas.forEach(r->porPar.put(r.getJogador().getId()+"-"+r.getPergunta().getId(),r));try(Workbook wb=new XSSFWorkbook()){CellStyle header=wb.createCellStyle();Font bold=wb.createFont();bold.setBold(true);header.setFont(bold);
        Sheet ps=wb.createSheet("Jogadores");Row h=ps.createRow(0);String[] ph={"Posição","Participante","Avatar","Pontuação","Acertos (%)","Sem resposta"};for(int c=0;c<ph.length;c++){h.createCell(c).setCellValue(ph[c]);h.getCell(c).setCellStyle(header);}for(int i=0;i<ordem.size();i++){QuizJogador j=ordem.get(i);List<QuizResposta> rs=todas.stream().filter(r->r.getJogador().getId().equals(j.getId())).toList();long ok=rs.stream().filter(QuizResposta::isCorreta).count();Row row=ps.createRow(i+1);row.createCell(0).setCellValue(i+1);row.createCell(1).setCellValue(j.getUsuario().getNome());row.createCell(2).setCellValue(j.getAvatar());row.createCell(3).setCellValue(j.getPontuacao());row.createCell(4).setCellValue(q.getPerguntas().isEmpty()?0:100.0*ok/q.getPerguntas().size());row.createCell(5).setCellValue(Math.max(0,q.getPerguntas().size()-rs.size()));}
        Sheet qs=wb.createSheet("Perguntas");String[] qh={"Nº","Pergunta","Dificuldade","Corretas","Incorretas","Sem resposta","Acerto (%)","Tempo médio (ms)"};Row qrow=qs.createRow(0);for(int c=0;c<qh.length;c++){qrow.createCell(c).setCellValue(qh[c]);qrow.getCell(c).setCellStyle(header);}for(int i=0;i<q.getPerguntas().size();i++){QuizPergunta p=q.getPerguntas().get(i);List<QuizResposta> rs=todas.stream().filter(r->r.getPergunta().getId().equals(p.getId())).toList();long ok=rs.stream().filter(QuizResposta::isCorreta).count();Row row=qs.createRow(i+1);row.createCell(0).setCellValue(i+1);row.createCell(1).setCellValue(p.getEnunciado());row.createCell(2).setCellValue(p.getDificuldade().name());row.createCell(3).setCellValue(ok);row.createCell(4).setCellValue(rs.size()-ok);row.createCell(5).setCellValue(Math.max(0,ordem.size()-rs.size()));row.createCell(6).setCellValue(ordem.isEmpty()?0:100.0*ok/ordem.size());row.createCell(7).setCellValue(rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0));}
        Sheet as=wb.createSheet("Respostas");String[] ah={"Participante","Pergunta","Alternativa marcada","Correta","Pontos","Tempo (ms)"};Row arow=as.createRow(0);for(int c=0;c<ah.length;c++){arow.createCell(c).setCellValue(ah[c]);arow.getCell(c).setCellStyle(header);}int ri=1;for(QuizJogador j:ordem)for(QuizPergunta p:q.getPerguntas()){QuizResposta a=porPar.get(j.getId()+"-"+p.getId());Row row=as.createRow(ri++);row.createCell(0).setCellValue(j.getUsuario().getNome());row.createCell(1).setCellValue(p.getEnunciado());row.createCell(2).setCellValue(a==null?"Sem resposta":a.getAlternativa().getTexto());row.createCell(3).setCellValue(a!=null&&a.isCorreta()?"Sim":"Não");row.createCell(4).setCellValue(a==null?0:a.getPontos());row.createCell(5).setCellValue(a==null?0:a.getTempoMs());}
        for(Sheet s:List.of(ps,qs,as))for(int c=0;c<s.getRow(0).getLastCellNum();c++)s.autoSizeColumn(c);res.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");res.setHeader("Content-Disposition","attachment; filename=quiz-"+id+"-relatorio.xlsx");wb.write(res.getOutputStream());}}
    @GetMapping("/organizador/quizzes/{id}/relatorio.csv") public void csv(@PathVariable Long id,Authentication auth,HttpServletResponse res)throws IOException{Quiz q=owned(id,auth);res.setContentType("text/csv;charset=UTF-8");res.setHeader("Content-Disposition","attachment; filename=quiz-"+id+"-relatorio.csv");res.getWriter().write("\uFEFFJogador;Posição;Pontuação;Avatar\n");int i=0;for(QuizJogador j:rank(q))res.getWriter().write(csvEscape(j.getUsuario().getNome())+";"+(++i)+";"+j.getPontuacao()+";"+j.getAvatar()+"\n");res.getWriter().write("\nPergunta;Corretas;Incorretas;Sem resposta;Tempo médio (ms)\n");for(QuizPergunta p:q.getPerguntas()){List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long ok=rs.stream().filter(QuizResposta::isCorreta).count();double avg=rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0);res.getWriter().write(csvEscape(p.getEnunciado())+";"+ok+";"+(rs.size()-ok)+";"+(q.getJogadores().size()-rs.size())+";"+Math.round(avg)+"\n");}}
    private Map<String,Object> reportStats(Quiz q){List<QuizResposta> all=respostas.findByJogadorQuizId(q.getId());long correct=all.stream().filter(QuizResposta::isCorreta).count();long total=(long)q.getJogadores().size()*q.getPerguntas().size();return Map.of("participantes",q.getJogadores().size(),"perguntas",q.getPerguntas().size(),"acerto",total==0?0:Math.round(100.0*correct/total),"semResposta",Math.max(0,total-all.size()),"duracao",q.getIniciadoEm()==null?0:Duration.between(q.getIniciadoEm(),q.getEncerradoEm()==null?LocalDateTime.now():q.getEncerradoEm()).toMinutes());}
    private List<Map<String,Object>> questionReports(Quiz q){List<Map<String,Object>> out=new ArrayList<>();for(QuizPergunta p:q.getPerguntas()){List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long correct=rs.stream().filter(QuizResposta::isCorreta).count();out.add(Map.of("pergunta",p,"corretas",correct,"incorretas",rs.size()-correct,"semResposta",Math.max(0,q.getJogadores().size()-rs.size()),"percentual",q.getJogadores().isEmpty()?0:Math.round(100.0*correct/q.getJogadores().size()),"tempoMedio",Math.round(rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0))));}return out;}
    private Map<String,Object> roundStats(Quiz q){if(q.getPerguntaAtual()<0||q.getPerguntaAtual()>=q.getPerguntas().size())return Map.of("corretas",0,"incorretas",0,"semResposta",q.getJogadores().size());QuizPergunta p=q.getPerguntas().get(q.getPerguntaAtual());List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long correct=rs.stream().filter(QuizResposta::isCorreta).count();return Map.of("corretas",correct,"incorretas",rs.size()-correct,"semResposta",Math.max(0,q.getJogadores().size()-rs.size()));}
    private List<Map<String,Object>> playerReports(Quiz q){List<QuizResposta> all=respostas.findByJogadorQuizId(q.getId());List<Map<String,Object>> out=new ArrayList<>();int pos=0;for(QuizJogador j:rank(q)){List<QuizResposta> rs=all.stream().filter(x->x.getJogador().getId().equals(j.getId())).toList();long correct=rs.stream().filter(QuizResposta::isCorreta).count();out.add(Map.of("jogador",j,"posicao",++pos,"corretas",correct,"percentual",q.getPerguntas().isEmpty()?0:Math.round(100.0*correct/q.getPerguntas().size()),"semResposta",Math.max(0,q.getPerguntas().size()-rs.size())));}double media=out.stream().mapToInt(x->(Integer)x.get("percentual")).average().orElse(0);for(Map<String,Object> row:out)row.put("abaixoMedia",(Integer)row.get("percentual")<media);return out;}
    private List<QuizJogador> rank(Quiz q){return q.getJogadores().stream().sorted(Comparator.comparing(QuizJogador::getPontuacao).reversed().thenComparing(QuizJogador::getEntrouEm)).toList();}
    private String qr(String codigo){try{String url=org.springframework.web.servlet.support.ServletUriComponentsBuilder.fromCurrentContextPath().path("/quiz/entrar/{codigo}").buildAndExpand(codigo).toUriString();ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(new QRCodeWriter().encode(url,BarcodeFormat.QR_CODE,280,280),"PNG",out);return "data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());}catch(Exception e){return "";}}
    private Quiz owned(Long id,Authentication a){Quiz q=quizzes.findFullById(id).orElseThrow();if(!q.getOrganizador().getId().equals(usuario(a).getId()))throw new RuntimeException("Acesso negado.");return q;}
    private Usuario usuario(Authentication a){return usuarios.findByEmailIgnoreCase(a.getName()).orElseThrow();}
    private String codigo(){String chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";String x;do{x=new java.security.SecureRandom().ints(6,0,chars.length()).mapToObj(chars::charAt).map(String::valueOf).collect(Collectors.joining());}while(quizzes.findByCodigoIgnoreCase(x).isPresent());return x;}
    private int valor(Integer x,int d){return x==null?d:Math.max(1,Math.min(10000,x));} private String blank(String x){return x==null||x.isBlank()?null:x.trim();} private String avatar(String x){return List.of("astronauta","raposa","gato","robo","coruja","capivara").contains(x)?x:"astronauta";}
    private String csvEscape(String s){return "\""+s.replace("\"","\"\"")+"\"";}
    public static class QuizInput {public String titulo,descricao; public Integer pontosFacil,pontosMedio,pontosDificil,quantidadeFacil,quantidadeMedio,quantidadeDificil; public List<QuestionInput> perguntas;}
    public static class QuestionInput {public Long bancoId;public String enunciado,imagemUrl,dificuldade;public Integer segundos;public Boolean bonus;public List<OptionInput> alternativas;}
    public static class OptionInput {public String texto,imagemUrl;public boolean correta;}
}
